import React, { useState } from 'react';

function ShoppingList({ recipes, planner }) {
  const [checked, setChecked] = useState({});
  const [extraItems, setExtraItems] = useState([]);
  const [newItem, setNewItem] = useState('');

  function generateList() {
    const items = {};
    Object.values(planner).forEach(meal => {
      if (!meal || !meal.ingredients) return;
      meal.ingredients.forEach(ing => {
        const key = `${ing.name}_${ing.unit}`;
        if (items[key]) {
          items[key].amount += parseFloat(ing.amount) || 0;
        } else {
          items[key] = { name: ing.name, amount: parseFloat(ing.amount) || 0, unit: ing.unit };
        }
      });
    });
    return Object.values(items);
  }

  function toggleChecked(key) {
    setChecked({ ...checked, [key]: !checked[key] });
  }

  function addExtraItem() {
    if (!newItem.trim()) return;
    setExtraItems([...extraItems, { id: Date.now(), name: newItem.trim() }]);
    setNewItem('');
  }

  function removeExtra(id) {
    setExtraItems(extraItems.filter(i => i.id !== id));
  }

  function clearChecked() {
    setChecked({});
  }

  const generatedItems = generateList();
  const unchecked = generatedItems.filter(i => !checked[`${i.name}_${i.unit}`]);
  const checkedItems = generatedItems.filter(i => checked[`${i.name}_${i.unit}`]);

  return (
    <div>
      {/* Header row */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
        <p style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>
          {generatedItems.length} items from this week's plan
        </p>
        {Object.keys(checked).length > 0 && (
          <button onClick={clearChecked} style={{
            background: 'none', border: 'none', color: 'var(--accent)',
            fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer',
          }}>Clear checked</button>
        )}
      </div>

      {/* Empty state */}
      {generatedItems.length === 0 && extraItems.length === 0 && (
        <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
          <p style={{ fontSize: '28px', marginBottom: '12px' }}>🛒</p>
          <p style={{ fontSize: '14px' }}>Plan your meals first and your shopping list will appear here</p>
        </div>
      )}

      {/* Unchecked items */}
      {unchecked.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginBottom: '16px' }}>
          {unchecked.map(item => {
            const key = `${item.name}_${item.unit}`;
            return (
              <div key={key} onClick={() => toggleChecked(key)} style={{
                backgroundColor: 'var(--white)', borderRadius: '12px',
                padding: '14px 16px', display: 'flex', alignItems: 'center',
                gap: '12px', cursor: 'pointer',
              }}>
                <div style={{
                  width: '22px', height: '22px', borderRadius: '50%',
                  border: '1.5px solid var(--border)', flexShrink: 0,
                }} />
                <span style={{ flex: 1, fontSize: '14px' }}>{item.name}</span>
                <span style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>
                  {Math.round(item.amount * 10) / 10} {item.unit}
                </span>
              </div>
            );
          })}
        </div>
      )}

      {/* Extra items */}
      {extraItems.filter(i => !checked[`extra_${i.id}`]).length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginBottom: '16px' }}>
          {extraItems.filter(i => !checked[`extra_${i.id}`]).map(item => (
            <div key={item.id} style={{
              backgroundColor: 'var(--white)', borderRadius: '12px',
              padding: '14px 16px', display: 'flex', alignItems: 'center', gap: '12px',
            }}>
              <div onClick={() => toggleChecked(`extra_${item.id}`)} style={{
                width: '22px', height: '22px', borderRadius: '50%',
                border: '1.5px solid var(--border)', flexShrink: 0, cursor: 'pointer',
              }} />
              <span style={{ flex: 1, fontSize: '14px' }}>{item.name}</span>
              <button onClick={() => removeExtra(item.id)} style={{
                background: 'none', border: 'none', color: 'var(--border)',
                fontSize: '16px', cursor: 'pointer',
              }}>✕</button>
            </div>
          ))}
        </div>
      )}

      {/* Add extra item */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '24px' }}>
        <input
          value={newItem}
          onChange={e => setNewItem(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && addExtraItem()}
          placeholder="Add extra item..."
          style={{
            flex: 1, padding: '12px 14px', borderRadius: '10px',
            border: '1px solid var(--border)', backgroundColor: 'var(--white)',
            fontFamily: 'Jost, sans-serif', fontSize: '14px',
            color: 'var(--text-primary)', outline: 'none',
          }}
        />
        <button onClick={addExtraItem} style={{
          padding: '12px 16px', borderRadius: '10px', border: 'none',
          backgroundColor: 'var(--accent)', color: 'var(--white)',
          fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
        }}>+</button>
      </div>

      {/* Checked items */}
      {(checkedItems.length > 0 || extraItems.filter(i => checked[`extra_${i.id}`]).length > 0) && (
        <div>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px' }}>ALREADY GOT</p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {checkedItems.map(item => {
              const key = `${item.name}_${item.unit}`;
              return (
                <div key={key} onClick={() => toggleChecked(key)} style={{
                  backgroundColor: 'var(--white)', borderRadius: '12px',
                  padding: '14px 16px', display: 'flex', alignItems: 'center',
                  gap: '12px', cursor: 'pointer', opacity: 0.5,
                }}>
                  <div style={{
                    width: '22px', height: '22px', borderRadius: '50%',
                    border: '1.5px solid var(--accent)', backgroundColor: 'var(--accent)',
                    flexShrink: 0, display: 'flex', alignItems: 'center',
                    justifyContent: 'center', color: 'var(--white)', fontSize: '12px',
                  }}>✓</div>
                  <span style={{ flex: 1, fontSize: '14px', textDecoration: 'line-through' }}>{item.name}</span>
                  <span style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>
                    {Math.round(item.amount * 10) / 10} {item.unit}
                  </span>
                </div>
              );
            })}
            {extraItems.filter(i => checked[`extra_${i.id}`]).map(item => (
              <div key={item.id} onClick={() => toggleChecked(`extra_${item.id}`)} style={{
                backgroundColor: 'var(--white)', borderRadius: '12px',
                padding: '14px 16px', display: 'flex', alignItems: 'center',
                gap: '12px', cursor: 'pointer', opacity: 0.5,
              }}>
                <div style={{
                  width: '22px', height: '22px', borderRadius: '50%',
                  border: '1.5px solid var(--accent)', backgroundColor: 'var(--accent)',
                  flexShrink: 0, display: 'flex', alignItems: 'center',
                  justifyContent: 'center', color: 'var(--white)', fontSize: '12px',
                }}>✓</div>
                <span style={{ flex: 1, fontSize: '14px', textDecoration: 'line-through' }}>{item.name}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default ShoppingList;