import React, { useState } from 'react';

const DAYS_SHORT = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

const EVENT_COLORS = ['#A0856C', '#7A9E87', '#7A8FA6', '#B85C5C', '#9B7AB8', '#C4A035'];

const emptyEvent = {
  title: '', date: new Date().toISOString().split('T')[0],
  time: '', endTime: '', color: '#A0856C', notes: '', type: 'event',
};

function getDaysInMonth(year, month) {
  return new Date(year, month + 1, 0).getDate();
}

function getFirstDayOfMonth(year, month) {
  const day = new Date(year, month, 1).getDay();
  return (day + 6) % 7;
}

function getWeekDates(date) {
  const day = date.getDay();
  const monday = new Date(date);
  monday.setDate(date.getDate() - ((day + 6) % 7));
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    return d;
  });
}

function toDateStr(date) {
  return date.toISOString().split('T')[0];
}

function formatTime(timeStr) {
  if (!timeStr) return '';
  return timeStr;
}

function Calendar({ tasks, shifts, workoutLogs, events, setEvents, relations, mealPlanner, recipes }) {
  const [view, setView] = useState('month');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(toDateStr(new Date()));
  const [showEventModal, setShowEventModal] = useState(false);
  const [showDayModal, setShowDayModal] = useState(false);
  const [eventForm, setEventForm] = useState(emptyEvent);
  const [editingId, setEditingId] = useState(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);

  const today = toDateStr(new Date());

  // Gather all items for a date
  function getItemsForDate(dateStr) {
    const items = [];

    // Custom events
    (events || []).filter(e => e.date === dateStr).forEach(e => items.push({ ...e, _type: 'event' }));

    // Tasks due
    (tasks || []).filter(t => t.dueDate === dateStr && !t.completed).forEach(t => items.push({ ...t, _type: 'task', color: '#B85C5C', title: t.title }));

    // Work shifts
    (shifts || []).filter(s => s.date === dateStr).forEach(s => items.push({ ...s, _type: 'shift', color: '#7A8FA6', title: `Work ${s.start}–${s.end}` }));

    // Workout logs
    (workoutLogs || []).filter(w => w.date === dateStr).forEach(w => items.push({ ...w, _type: 'workout', color: '#7A9E87', title: w.planTitle || 'Workout' }));

    // Birthdays
    (relations || []).filter(p => {
      if (!p.birthday) return false;
      const bday = new Date(p.birthday + 'T00:00:00');
      const date = new Date(dateStr + 'T00:00:00');
      return bday.getMonth() === date.getMonth() && bday.getDate() === date.getDate();
    }).forEach(p => items.push({ id: `bday_${p.id}`, _type: 'birthday', color: '#9B7AB8', title: `🎂 ${p.name}'s birthday` }));

    // Meal prep (day before a planned meal day)
    const nextDay = new Date(dateStr + 'T00:00:00');
    nextDay.setDate(nextDay.getDate() + 1);
    const nextDayStr = toDateStr(nextDay);
    const hasMealsTomorrow = Object.keys(mealPlanner || {}).some(key => key.startsWith(nextDayStr));
    if (hasMealsTomorrow) {
      items.push({ id: `prep_${dateStr}`, _type: 'prep', color: '#C4A035', title: '🥗 Meal prep for tomorrow' });
    }

    return items;
  }

  function saveEvent() {
    if (!eventForm.title.trim()) return;
    if (editingId) {
      setEvents(events.map(e => e.id === editingId ? { ...e, ...eventForm } : e));
    } else {
      setEvents([...(events || []), { ...eventForm, id: Date.now() }]);
    }
    setShowEventModal(false);
    setEditingId(null);
  }

  function deleteEvent(id) {
    setEvents(events.filter(e => e.id !== id));
    setShowDeleteConfirm(null);
  }

  // MONTH VIEW
  function renderMonth() {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);
    const cells = [];

    for (let i = 0; i < firstDay; i++) cells.push(null);
    for (let d = 1; d <= daysInMonth; d++) cells.push(d);

    return (
      <div>
        {/* Day headers */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', marginBottom: '4px' }}>
          {DAYS_SHORT.map(d => (
            <div key={d} style={{ textAlign: 'center', fontSize: '10px', color: 'var(--text-secondary)', letterSpacing: '0.05em', padding: '4px 0' }}>{d.toUpperCase()}</div>
          ))}
        </div>

        {/* Calendar grid */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '2px' }}>
          {cells.map((day, i) => {
            if (!day) return <div key={`empty_${i}`} />;
            const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
            const items = getItemsForDate(dateStr);
            const isToday = dateStr === today;
            const isSelected = dateStr === selectedDate;

            return (
              <div key={dateStr} onClick={() => { setSelectedDate(dateStr); setShowDayModal(true); }} style={{
                padding: '6px 2px', borderRadius: '8px', cursor: 'pointer', minHeight: '52px',
                backgroundColor: isSelected ? 'var(--accent)' : isToday ? 'var(--surface)' : 'transparent',
                border: isToday && !isSelected ? '1.5px solid var(--accent)' : '1.5px solid transparent',
              }}>
                <p style={{ fontSize: '12px', fontWeight: isToday ? '600' : '400', color: isSelected ? 'var(--white)' : isToday ? 'var(--accent)' : 'var(--text-primary)', textAlign: 'center', marginBottom: '3px' }}>{day}</p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1px', alignItems: 'center' }}>
                  {items.slice(0, 2).map((item, idx) => (
                    <div key={idx} style={{ width: '6px', height: '6px', borderRadius: '50%', backgroundColor: isSelected ? 'rgba(255,255,255,0.8)' : item.color }} />
                  ))}
                  {items.length > 2 && <p style={{ fontSize: '8px', color: isSelected ? 'rgba(255,255,255,0.7)' : 'var(--text-secondary)' }}>+{items.length - 2}</p>}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  // WEEK VIEW
  function renderWeek() {
    const weekDates = getWeekDates(currentDate);
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        {weekDates.map(date => {
          const dateStr = toDateStr(date);
          const items = getItemsForDate(dateStr);
          const isToday = dateStr === today;
          return (
            <div key={dateStr} onClick={() => { setSelectedDate(dateStr); setShowDayModal(true); }} style={{
              backgroundColor: 'var(--white)', borderRadius: '12px', padding: '12px 14px', cursor: 'pointer',
              borderLeft: isToday ? '4px solid var(--accent)' : '4px solid transparent',
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: items.length > 0 ? '8px' : '0' }}>
                <p style={{ fontSize: '13px', fontWeight: isToday ? '600' : '400', color: isToday ? 'var(--accent)' : 'var(--text-primary)' }}>
                  {date.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' })}
                </p>
                {items.length === 0 && <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>Free</p>}
              </div>
              {items.map((item, idx) => (
                <div key={idx} style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                  <div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: item.color, flexShrink: 0 }} />
                  <p style={{ fontSize: '12px', color: 'var(--text-primary)' }}>{item.title}{item.time ? ` · ${item.time}` : ''}</p>
                </div>
              ))}
            </div>
          );
        })}
      </div>
    );
  }

  // DAY VIEW
  function renderDay() {
    const items = getItemsForDate(selectedDate);
    const date = new Date(selectedDate + 'T00:00:00');
    return (
      <div>
        <p style={{ fontSize: '16px', fontWeight: '500', marginBottom: '16px' }}>
          {date.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' })}
        </p>
        {items.length === 0 ? (
          <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', marginTop: '40px' }}>Nothing planned for this day</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {items.map((item, idx) => (
              <div key={idx} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px 16px', borderLeft: `4px solid ${item.color}` }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <div>
                    <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '2px' }}>{item.title}</p>
                    {item.time && <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{formatTime(item.time)}{item.endTime ? ` – ${item.endTime}` : ''}</p>}
                    {item.notes && <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginTop: '4px' }}>{item.notes}</p>}
                    <p style={{ fontSize: '10px', color: 'var(--text-secondary)', marginTop: '4px', letterSpacing: '0.05em', textTransform: 'uppercase' }}>{item._type}</p>
                  </div>
                  {item._type === 'event' && (
                    <button onClick={() => setShowDeleteConfirm(item.id)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
        <button onClick={() => { setEventForm({ ...emptyEvent, date: selectedDate }); setEditingId(null); setShowEventModal(true); }} style={{
          width: '100%', padding: '14px', borderRadius: '12px',
          border: '1.5px dashed var(--border)', backgroundColor: 'transparent',
          color: 'var(--text-secondary)', fontFamily: 'Jost, sans-serif',
          fontSize: '13px', cursor: 'pointer', marginTop: '16px',
        }}>+ Add event</button>
      </div>
    );
  }

  function prevPeriod() {
    const d = new Date(currentDate);
    if (view === 'month') d.setMonth(d.getMonth() - 1);
    if (view === 'week') d.setDate(d.getDate() - 7);
    if (view === 'day') d.setDate(d.getDate() - 1);
    setCurrentDate(d);
    if (view === 'day') setSelectedDate(toDateStr(d));
  }

  function nextPeriod() {
    const d = new Date(currentDate);
    if (view === 'month') d.setMonth(d.getMonth() + 1);
    if (view === 'week') d.setDate(d.getDate() + 7);
    if (view === 'day') d.setDate(d.getDate() + 1);
    setCurrentDate(d);
    if (view === 'day') setSelectedDate(toDateStr(d));
  }

  function getPeriodLabel() {
    if (view === 'month') return `${MONTHS[currentDate.getMonth()]} ${currentDate.getFullYear()}`;
    if (view === 'week') {
      const weekDates = getWeekDates(currentDate);
      const first = weekDates[0];
      const last = weekDates[6];
      return `${first.getDate()} – ${last.getDate()} ${MONTHS[last.getMonth()]}`;
    }
    if (view === 'day') return new Date(selectedDate + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
    return '';
  }

  return (
    <div style={{ padding: '32px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>SCHEDULE</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '20px' }}>Calendar</h1>

      {/* View toggle */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
        {['month', 'week', 'day'].map(v => (
          <button key={v} onClick={() => { setView(v); if (v === 'day') setSelectedDate(today); }} style={{
            padding: '6px 14px', borderRadius: '20px', border: '1px solid',
            borderColor: view === v ? 'var(--accent)' : 'var(--border)',
            backgroundColor: view === v ? 'var(--accent)' : 'transparent',
            color: view === v ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '12px', fontFamily: 'Jost, sans-serif', fontWeight: '500',
            letterSpacing: '0.05em', cursor: 'pointer', textTransform: 'uppercase',
          }}>{v}</button>
        ))}
        <button onClick={() => { setCurrentDate(new Date()); setSelectedDate(today); }} style={{
          marginLeft: 'auto', padding: '6px 14px', borderRadius: '20px',
          border: '1px solid var(--border)', backgroundColor: 'transparent',
          color: 'var(--text-secondary)', fontFamily: 'Jost, sans-serif',
          fontSize: '12px', cursor: 'pointer',
        }}>Today</button>
      </div>

      {/* Period navigator */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '20px' }}>
        <button onClick={prevPeriod} style={{ background: 'none', border: 'none', fontSize: '22px', color: 'var(--text-secondary)', cursor: 'pointer', padding: '4px 10px' }}>‹</button>
        <span style={{ fontSize: '15px', fontWeight: '500' }}>{getPeriodLabel()}</span>
        <button onClick={nextPeriod} style={{ background: 'none', border: 'none', fontSize: '22px', color: 'var(--text-secondary)', cursor: 'pointer', padding: '4px 10px' }}>›</button>
      </div>

      {/* Legend */}
      <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap', marginBottom: '20px' }}>
        {[
          { label: 'Event', color: '#A0856C' },
          { label: 'Task', color: '#B85C5C' },
          { label: 'Work', color: '#7A8FA6' },
          { label: 'Workout', color: '#7A9E87' },
          { label: 'Birthday', color: '#9B7AB8' },
          { label: 'Meal prep', color: '#C4A035' },
        ].map(item => (
          <div key={item.label} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
            <div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: item.color }} />
            <span style={{ fontSize: '10px', color: 'var(--text-secondary)' }}>{item.label}</span>
          </div>
        ))}
      </div>

      {/* Calendar content */}
      {view === 'month' && renderMonth()}
      {view === 'week' && renderWeek()}
      {view === 'day' && renderDay()}

      {/* FAB */}
      <button onClick={() => { setEventForm({ ...emptyEvent, date: selectedDate }); setEditingId(null); setShowEventModal(true); }} style={{
        position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
        width: '52px', height: '52px', borderRadius: '50%',
        backgroundColor: 'var(--accent)', color: 'var(--white)', fontSize: '26px',
        border: 'none', cursor: 'pointer', boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
      }}>+</button>

      {/* Day detail modal (month view) */}
      {showDayModal && view === 'month' && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '80vh', overflowY: 'auto' }}>
            {renderDay()}
            <button onClick={() => setShowDayModal(false)} style={{ width: '100%', padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer', marginTop: '12px' }}>Close</button>
          </div>
        </div>
      )}

      {/* Delete confirm */}
      {showDeleteConfirm && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 300 }}>
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Delete event?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>This cannot be undone.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={() => deleteEvent(showDeleteConfirm)} style={deleteBtnStyle}>Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* Event modal */}
      {showEventModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 300 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>{editingId ? 'Edit Event' : 'New Event'}</h3>
            <label style={labelStyle}>TITLE</label>
            <input value={eventForm.title} onChange={e => setEventForm({ ...eventForm, title: e.target.value })} placeholder="Event name" style={inputStyle} />
            <label style={labelStyle}>DATE</label>
            <input type="date" value={eventForm.date} onChange={e => setEventForm({ ...eventForm, date: e.target.value })} style={inputStyle} />
            <div style={{ display: 'flex', gap: '12px', marginBottom: '20px' }}>
              <div style={{ flex: 1 }}>
                <label style={labelStyle}>START TIME</label>
                <input type="time" value={eventForm.time} onChange={e => setEventForm({ ...eventForm, time: e.target.value })} style={{ ...inputStyle, marginBottom: 0 }} />
              </div>
              <div style={{ flex: 1 }}>
                <label style={labelStyle}>END TIME</label>
                <input type="time" value={eventForm.endTime} onChange={e => setEventForm({ ...eventForm, endTime: e.target.value })} style={{ ...inputStyle, marginBottom: 0 }} />
              </div>
            </div>
            <label style={labelStyle}>COLOUR</label>
            <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
              {EVENT_COLORS.map(c => (
                <button key={c} onClick={() => setEventForm({ ...eventForm, color: c })} style={{ width: '32px', height: '32px', borderRadius: '50%', backgroundColor: c, border: eventForm.color === c ? '3px solid var(--text-primary)' : '3px solid transparent', cursor: 'pointer', outline: 'none' }} />
              ))}
            </div>
            <label style={labelStyle}>NOTES</label>
            <textarea value={eventForm.notes} onChange={e => setEventForm({ ...eventForm, notes: e.target.value })} placeholder="Optional notes" rows={3} style={{ ...inputStyle, resize: 'none' }} />
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowEventModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveEvent} style={saveBtnStyle}>{editingId ? 'Save Changes' : 'Add Event'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500' };
const inputStyle = { width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '20px', outline: 'none' };
const cancelBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const saveBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const deleteBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--danger)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };

export default Calendar;