import React, { useState } from 'react';
import { BrowserRouter, Routes, Route, NavLink, useLocation, useNavigate } from 'react-router-dom';
import './index.css';

import Home from './pages/Home';
import Tasks from './pages/Tasks';
import Habits from './pages/Habits';
import Finance from './pages/Finance';
import Meals from './pages/Meals';
import Outfit from './pages/Outfit';
import Settings from './pages/Settings';
import Work from './pages/Work';
import Workout from './pages/Workout';
import Relations from './pages/Relations';
import Calendar from './pages/Calendar';

function AppContent() {
  const [tasks, setTasks] = useState([]);
  const [habits, setHabits] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [budgets, setBudgets] = useState({});
  const [savings, setSavings] = useState([]);
  const [recipes, setRecipes] = useState([]);
  const [mealPlanner, setMealPlanner] = useState({});
  const [wardrobe, setWardrobe] = useState([]);
  const [outfitPlanner, setOutfitPlanner] = useState({});
  const [shifts, setShifts] = useState([]);
  const [workTasks, setWorkTasks] = useState([]);
  const [meetings, setMeetings] = useState([]);
  const [workouts, setWorkouts] = useState([]);
  const [workoutLogs, setWorkoutLogs] = useState([]);
  const [relations, setRelations] = useState([]);
  const [events, setEvents] = useState([]);
  const [showMore, setShowMore] = useState(false);
  const location = useLocation();

  const mainNav = [
    { to: '/', label: 'Home', icon: '⌂', exact: true },
    { to: '/tasks', label: 'Tasks', icon: '✓' },
    { to: '/habits', label: 'Habits', icon: '◎' },
    { to: '/calendar', label: 'Calendar', icon: '▦' },
    { to: '/meals', label: 'Meals', icon: '❧' },
  ];

  const morePages = [
    { to: '/outfit', label: 'Outfit', icon: '◇' },
    { to: '/finance', label: 'Finance', icon: '◈' },
    { to: '/work', label: 'Work', icon: '⊞' },
    { to: '/workout', label: 'Workout', icon: '◉' },
    { to: '/relations', label: 'Relations', icon: '♡' },
    { to: '/settings', label: 'Settings', icon: '⚙' },
  ];

  return (
    <div>
      <div style={{ paddingBottom: 'var(--nav-height)' }}>
        <Routes>
          <Route path="/" element={<Home tasks={tasks} habits={habits} transactions={transactions} mealPlanner={mealPlanner} outfitPlanner={outfitPlanner} shifts={shifts} workouts={workoutLogs} events={events} relations={relations} />} />
          <Route path="/tasks" element={<Tasks tasks={tasks} setTasks={setTasks} />} />
          <Route path="/habits" element={<Habits habits={habits} setHabits={setHabits} />} />
          <Route path="/finance" element={<Finance transactions={transactions} setTransactions={setTransactions} budgets={budgets} setBudgets={setBudgets} savings={savings} setSavings={setSavings} />} />
          <Route path="/meals" element={<Meals recipes={recipes} setRecipes={setRecipes} planner={mealPlanner} setPlanner={setMealPlanner} />} />
          <Route path="/outfit" element={<Outfit wardrobe={wardrobe} setWardrobe={setWardrobe} outfitPlanner={outfitPlanner} setOutfitPlanner={setOutfitPlanner} />} />
          <Route path="/work" element={<Work shifts={shifts} setShifts={setShifts} workTasks={workTasks} setWorkTasks={setWorkTasks} meetings={meetings} setMeetings={setMeetings} />} />
          <Route path="/workout" element={<Workout workouts={workouts} setWorkouts={setWorkouts} workoutLogs={workoutLogs} setWorkoutLogs={setWorkoutLogs} />} />
          <Route path="/relations" element={<Relations relations={relations} setRelations={setRelations} />} />
          <Route path="/calendar" element={<Calendar tasks={tasks} shifts={shifts} workoutLogs={workoutLogs} events={events} setEvents={setEvents} relations={relations} mealPlanner={mealPlanner} recipes={recipes} />} />
          <Route path="/settings" element={<Settings />} />
        </Routes>
      </div>

      {/* Bottom nav */}
      <nav style={{
        position: 'fixed', bottom: 0, left: '50%', transform: 'translateX(-50%)',
        width: '100%', maxWidth: '390px', height: 'var(--nav-height)',
        backgroundColor: 'var(--white)', borderTop: '1px solid var(--border)',
        display: 'flex', alignItems: 'center', justifyContent: 'space-around', zIndex: 100,
      }}>
        {mainNav.map(item => (
          <NavLink key={item.to} to={item.to} end={item.exact} style={{ textDecoration: 'none', flex: 1, display: 'flex', justifyContent: 'center', padding: '8px 0' }}>
            {({ isActive }) => (
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '2px', color: isActive ? 'var(--accent)' : 'var(--text-secondary)', transition: 'color 0.2s' }}>
                <span style={{ fontSize: '18px' }}>{item.icon}</span>
                <span style={{ fontSize: '10px', fontWeight: isActive ? '600' : '400', letterSpacing: '0.05em' }}>{item.label.toUpperCase()}</span>
              </div>
            )}
          </NavLink>
        ))}

        {/* More button */}
        <button onClick={() => setShowMore(true)} style={{
          flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center',
          gap: '2px', background: 'none', border: 'none', cursor: 'pointer',
          color: morePages.some(p => location.pathname === p.to) ? 'var(--accent)' : 'var(--text-secondary)',
          padding: '8px 0',
        }}>
          <span style={{ fontSize: '18px' }}>···</span>
          <span style={{ fontSize: '10px', letterSpacing: '0.05em' }}>MORE</span>
        </button>
      </nav>

      {/* More menu overlay */}
      {showMore && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', zIndex: 200, display: 'flex', alignItems: 'flex-end', justifyContent: 'center' }}
          onClick={() => setShowMore(false)}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}
            onClick={e => e.stopPropagation()}>
            <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '16px' }}>MORE PAGES</p>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px', marginBottom: '20px' }}>
              {morePages.map(page => (
                <NavLink key={page.to} to={page.to} onClick={() => setShowMore(false)}
                  style={{ textDecoration: 'none' }}>
                  {({ isActive }) => (
                    <div style={{
                      backgroundColor: isActive ? 'var(--accent)' : 'var(--white)',
                      borderRadius: '14px', padding: '16px 12px',
                      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px',
                      border: '1px solid', borderColor: isActive ? 'var(--accent)' : 'var(--border)',
                    }}>
                      <span style={{ fontSize: '22px', color: isActive ? 'var(--white)' : 'var(--text-primary)' }}>{page.icon}</span>
                      <span style={{ fontSize: '11px', color: isActive ? 'var(--white)' : 'var(--text-secondary)', letterSpacing: '0.05em' }}>{page.label.toUpperCase()}</span>
                    </div>
                  )}
                </NavLink>
              ))}
            </div>
            <button onClick={() => setShowMore(false)} style={{
              width: '100%', padding: '14px', borderRadius: '12px',
              border: '1px solid var(--border)', backgroundColor: 'transparent',
              fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
            }}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}

export default App;